import numpy as np
def read_xyz(path):
    with open(path) as f:
        n = int(f.readline()); f.readline()
        elems, coords = [], []
        for _ in range(n):
            p = f.readline().split()
            elems.append(p[0]); coords.append([float(p[1]), float(p[2]), float(p[3])])
    return elems, np.array(coords)
el, xyz = read_xyz("answer.xyz")
n=len(el)
cov = {"H":0.31,"C":0.76,"N":0.71,"O":0.66,"F":0.57,"B":0.84,"Br":1.14,"Ag":1.45}
bondset=set()
for i in range(n):
    for j in range(i+1,n):
        if np.linalg.norm(xyz[i]-xyz[j]) < (cov[el[i]]+cov[el[j]])*1.25:
            bondset.add((i,j))
# 1-3 pairs
angle_pairs=set()
from collections import defaultdict
adj=defaultdict(list)
for i,j in bondset: adj[i].append(j); adj[j].append(i)
for i in range(n):
    for a in adj[i]:
        for b in adj[a]:
            if b>i: angle_pairs.add((i,b))
close=[]
for i in range(n):
    for j in range(i+1,n):
        if (i,j) in bondset or (i,j) in angle_pairs: continue
        dd=np.linalg.norm(xyz[i]-xyz[j])
        vd={"H":1.20,"C":1.70,"N":1.55,"O":1.52,"F":1.47,"B":1.92,"Br":1.85,"Ag":1.72}
        if dd < (vd[el[i]]+vd[el[j]])*0.75:
            close.append((i,j,el[i],el[j],round(float(dd),3)))
print("number of non-bonded close contacts (<0.75*vdW):", len(close))
for c in sorted(close,key=lambda x:x[4])[:10]: print(c)
